use localbrain_core::backend::{auto_work, db, references, Config};
use serde_json::{json, Value};
use std::{collections::BTreeMap, fs, os::unix::fs::PermissionsExt};
#[test]
fn historical_affinity_report_and_complete_navigation_match_frozen_python() {
    let temporary = tempfile::tempdir().unwrap();
    let root = fs::canonicalize(temporary.path()).unwrap();
    let config = Config::for_data_dir(root.join("data"));
    db::initialize(&config).unwrap();
    let connection = db::connect(&config).unwrap();
    connection.execute_batch(SQL).unwrap();
    fs::create_dir(&config.cache_dir).unwrap();
    fs::set_permissions(&config.cache_dir, fs::Permissions::from_mode(0o700)).unwrap();
    let folder = config.cache_dir.join("session-simulation");
    fs::create_dir(&folder).unwrap();
    fs::set_permissions(&folder, fs::Permissions::from_mode(0o700)).unwrap();
    let info = fs::metadata(&config.database_path).unwrap();
    use std::os::unix::fs::MetadataExt;
    let binding = references::hash_payload(&json!([
        fs::canonicalize(&config.database_path)
            .unwrap()
            .to_string_lossy(),
        info.dev(),
        info.ino()
    ]));
    for (name,text) in [("owner.json",json!({"owner":"localbrain.session-simulation.v1","database":binding,"expires_at":"2026-12-18T00:00:00+00:00"}).to_string()),("report.json",REPORT.into()),("writer.lock",String::new())]{let path=folder.join(name);fs::write(&path,text).unwrap();fs::set_permissions(path,fs::Permissions::from_mode(0o600)).unwrap();}
    let at = chrono::DateTime::parse_from_rfc3339("2026-11-18T00:00:00Z")
        .unwrap()
        .with_timezone(&chrono::Utc);
    let cases: Value = serde_json::from_str(CASES).unwrap();
    for (index, case) in cases.as_array().unwrap().iter().enumerate() {
        let params = case["params"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(key, value)| (key.clone(), value.as_str().unwrap().to_owned()))
            .collect::<BTreeMap<_, _>>();
        let value = auto_work::affinity_page(&config, &params, Some(at));
        assert_eq!(
            references::hash_payload(&value),
            case["hash"],
            "case {index} {params:?}: {value}"
        );
    }
}
